/* response versions */
.rv{padding:18px 18px 0}
.rv-body{display:flex;flex-direction:column;gap:10px;align-items:flex-start;min-height:96px}
.rv-text{font-size:18px;line-height:1.45;font-weight:600;letter-spacing:-.2px;transition:opacity .2s ease,transform .3s var(--ease)}
.rv-text.out{opacity:0;transform:translateY(4px)}
.rv-foot{display:flex;align-items:center;justify-content:space-between;margin:14px -18px 0;padding:10px 12px 10px 18px;border-top:1px solid var(--line)}
.rv-foot .ghost[disabled]{opacity:.4;cursor:default}
.rv-foot .rv-tag{margin-left:10px}

/* response versions: the standard chat pattern, pager and small actions under the reply */
.rv-foot{justify-content:flex-start;gap:2px;padding:2px 14px 14px;border-top:0}
.rv-foot .pager button{width:26px;height:26px}
.rv-div{width:1px;height:16px;margin:0 6px;background:var(--line)}
.rv-ib{width:28px;height:28px;display:grid;place-items:center;color:var(--muted);transition:color .2s,background-color .2s}
.rv-ib:hover:not(:disabled){color:var(--text);background:var(--chip)}
.rv-ib:disabled{opacity:.35;cursor:not-allowed}
.rv-ib.on[data-a="up"]{color:var(--accent)}
.rv-ib.on[data-a="down"]{color:var(--danger)}
.rv-body{padding-bottom:6px}
[data-style="soft"] .rv-ib{border-radius:8px}
#c31 .rv-text{font-size:15px;font-weight:400;line-height:1.6;letter-spacing:0;min-height:0}
#c31 .rv-body{min-height:0;padding-top:8px}

/* ---------- response versions ---------- */
{
  const pool = [['Concise','Simple plans that grow with your team.'],['Confident','Pick a plan today and ship your next release faster.'],['Friendly','Plans that fit how your team works, with no surprises.'],['Direct','Clear pricing, every feature listed, cancel any time.'],['Playful','Pricing so clear it barely needs a page.']];
  const versions = [0]; let cur = 0;
  const text = $('#rv-text'), tag = $('#rv-tag'), page = $('#rv-page'), regen = $('#rv-regen');
  function show(i, stream){
    cur = i; const [t, s] = pool[versions[i]];
    page.textContent = (i + 1) + ' / ' + versions.length; swapText(tag, t);
    regen.disabled = versions.length >= pool.length;
    if (stream){ text.innerHTML = wordsHTML(s); revealWords(text, 60, n => { if (n % 2 === 0) Sound.play('stream'); }); return; }
    text.classList.add('out'); setTimeout(() => { text.textContent = s; text.classList.remove('out'); }, 200);
  }
  $('#rv-prev').addEventListener('click', () => { if (cur > 0){ Sound.play('tab'); show(cur - 1); } });
  $('#rv-next').addEventListener('click', () => { if (cur < versions.length - 1){ Sound.play('tab'); show(cur + 1); } });
  regen.addEventListener('click', () => { if (versions.length >= pool.length) return; versions.push(versions.length); Sound.play('tab'); show(versions.length - 1, true); });
  text.textContent = pool[0][1]; page.textContent = '1 / 1';
}
/* ---------- response versions actions ---------- */
{
  $$('#c31 .rv-ib[data-a]').forEach(b => b.addEventListener('click', async () => {
    if (b.dataset.a === 'copy'){ if (await copyText($('#rv-text').textContent)){ Sound.play('copy'); showToast('Copied'); } return; }
    $$('#c31 .rv-ib[data-a="up"], #c31 .rv-ib[data-a="down"]').forEach(x => x.classList.toggle('on', x === b && !b.classList.contains('on')));
    Sound.play('select');
  }));
}
